CREATE TABLE room_message (id UUID PRIMARY KEY DEFAULT uuid_v7(),room_id UUID NOT NULL,author_id UUID NOT NULL,idempotency_key VARCHAR(256) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(room_id) REFERENCES room(id)); CREATE UNIQUE INDEX uq_room_message_idempotency ON room_message(room_id,author_id,idempotency_key); CREATE INDEX idx_room_message_timeline ON room_message(room_id,created_at,id);
